// PLG150-AN voice banks, embedded so the editor works when opened straight from disk.
// Each bank is 128 User Voice blocks of 1832 bytes (Common 0x668 + Scene 0x7A + Step Seq 0x46),
// gzip-compressed and base64-encoded. Generated from the voice tables of the C-PLG150-AN
// Ctrlr panel (https://sourceforge.net/projects/c-plg150-an/): Preset 1 and Preset 2 are
// the PLG150-AN preset banks, User is that panel's default user bank.
window.AN_BANKS = {
  "Preset 1": "",
  "Preset 2": "",
  "User": "",
};
